import HeroBanner from "../components/banner/HeroBanner";
import CategoryProductList from "../components/category/CategoryProductList";
import ProductList from "../components/product/ProductList";

function Home() {
    return (
        <div className="homepage-wrapper">
            {/* 1. Banner tràn viền cực sang */}
            <HeroBanner />

            {/* 2. Khối Danh Mục Sản Phẩm (Chạy hàng ngang) */}
            <section className="category-section py-5 bg-light">
                <div className="container">
                    <div className="text-center mb-4">
                        <h2 className="fw-semibold text-dark">Khám Phá Theo Danh Mục</h2>
                        <p className="text-muted small">Tìm kiếm nhanh những món đồ phù hợp cho không gian của bạn</p>
                    </div>
                    <CategoryProductList />
                </div>
            </section>

            {/* 3. Khối Sản Phẩm Nổi Bật (Chạy hàng ngang/Grid thoáng đãng) */}
            <section className="products-section py-5">
                <div className="container">
                    <div className="text-center mb-5">
                        <span className="text-uppercase tracking-wider small text-secondary">Sản phẩm nổi bật</span>
                        <h2 className="fw-bold text-dark mt-1">Nội Thất Thông Minh</h2>
                        <div className="mx-auto bg-dark mt-2" style={{ width: "50px", height: "2px" }}></div>
                    </div>
                    <ProductList />
                </div>
            </section>
        </div>
    );
}

export default Home;
